mapper.select:
SELECT so.id, so.order_no as orderNo, so.customer_id as customerId, so.customer_name as customerName, so.salesman_id as salesmanId, su.realname as salesmanName, so.order_date as orderDate, so.delivery_date as deliveryDate, so.delivery_consignee as consignee, so.delivery_phone as consigneePhone, so.delivery_address as consigneeAddress, COALESCE(detail_sum.totalQty, 0) as totalQty, COALESCE(delivery_sum.deliveredQty, 0) as deliveredQty, COALESCE(detail_sum.totalQty, 0) - COALESCE(delivery_sum.deliveredQty, 0) as remainingQty, CASE WHEN COALESCE(detail_sum.totalQty, 0) = 0 THEN '0' WHEN COALESCE(delivery_sum.deliveredQty, 0) = 0 THEN '0' WHEN COALESCE(delivery_sum.deliveredQty, 0) >= COALESCE(detail_sum.totalQty, 0) THEN '2' ELSE '1' END as deliveryStatus,
CASE WHEN so.delivery_date IS NOT NULL AND DATEDIFF(so.delivery_date, CURDATE()) BETWEEN 0 AND #{param.alertDays} THEN 1 ELSE 0 END as isUrgent
0 as isUrgent
FROM mis_sales_order so LEFT JOIN sys_user su ON so.salesman_id = su.id LEFT JOIN ( SELECT order_id, SUM(order_qty) as totalQty FROM mis_sales_order_detail GROUP BY order_id ) detail_sum ON detail_sum.order_id = so.id LEFT JOIN ( SELECT m.source_order_id, SUM(d.actual_qty) as deliveredQty FROM mis_delivery_detail d JOIN mis_delivery m ON d.delivery_id = m.id GROUP BY m.source_order_id ) delivery_sum ON delivery_sum.source_order_id = so.id WHERE so.order_status >= '2' AND so.sales_approve_status ='1' AND so.finance_approve_status='1'
AND so.order_no LIKE CONCAT('%', #{param.orderNo}, '%')
AND so.customer_name LIKE CONCAT('%', #{param.customerName}, '%')
AND so.salesman_id = #{param.salesmanId}
AND so.order_date >= #{param.orderDate_begin}
AND so.order_date <= #{param.orderDate_end}
AND so.delivery_date >= #{param.deliveryDate_begin}
AND so.delivery_date <= #{param.deliveryDate_end}
AND ( CASE WHEN COALESCE(detail_sum.totalQty, 0) = 0 THEN '0' WHEN COALESCE(delivery_sum.deliveredQty, 0) = 0 THEN '0' WHEN COALESCE(delivery_sum.deliveredQty, 0) >= COALESCE(detail_sum.totalQty, 0) THEN '2' ELSE '1' END ) = #{param.deliveryStatus}
AND COALESCE(delivery_sum.deliveredQty, 0) < COALESCE(detail_sum.totalQty, 0)
AND so.delivery_date IS NOT NULL AND DATEDIFF(so.delivery_date, CURDATE()) BETWEEN 0 AND #{param.alertDays}
ORDER BY
CASE WHEN so.delivery_date IS NOT NULL AND DATEDIFF(so.delivery_date, CURDATE()) BETWEEN 0 AND #{param.alertDays} THEN 0 ELSE 1 END ASC,
so.delivery_date ASC, so.order_date ASC
